"""Generate a transparent comparison of the baseline and the cautious experiment."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'frontend/public/models/rsl'
a=json.loads((OUT/'alphabet-report.json').read_text());b=json.loads((OUT/'alphabet-cautious-report.json').read_text())
rows=''.join(f'<tr><td>{html.escape(c["label"])}</td><td>{a["perClass"][i]["correct"]}/{c["tested"]}</td><td>{c["correct"]}/{c["tested"]}</td></tr>' for i,c in enumerate(b['perClass']))
score=lambda x:f'{x*100:.2f}%'
page=f'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Две модели распознавания — AI Mentor</title><style>body{{font:17px/1.7 system-ui;background:#f7f3eb;color:#2e3540;max-width:900px;padding:24px;margin:auto}}table{{border-collapse:collapse;width:100%;font-size:15px}}td,th{{padding:10px;text-align:left;border-bottom:1px solid #d4ccc0}}a{{color:#305c80}}code{{overflow-wrap:anywhere}}</style><h1>Больше данных: что изменилось на проверке</h1><p>Новая модель обучена на {b['trainVideos']} видео Bukva от {b['trainSigners']} людей. Google MediaPipe находит координаты кисти; собственная небольшая нейросеть определяет одну из 33 букв или отсутствие жеста. 474 входных признака, 96 скрытых ReLU-нейронов, 34 выхода. Работа локальная, без внешнего AI API.</p><h2>Одна и та же проверка</h2><p>Обе модели проверены на тех же {b['testVideos']} видео от {b['testSigners']} других людей. Пересечение людей с обучением: 0. Новые параметры выбраны на {b['validationVideos']} видео других исполнителей внутри обучающей части: сравнили три линейных модели и две нейросети. Проверочные видео не участвовали в выборе параметров.</p><table><tr><th>Показатель</th><th>Обычный режим</th><th>Осторожный режим</th></tr><tr><td>Обучающих видео</td><td>{a['trainVideos']}</td><td>{b['trainVideos']}</td></tr><tr><td>Точность на всех видео</td><td>{score(a['accuracy'])}</td><td>{score(b['accuracy'])}</td></tr><tr><td>Доля выданных ответов</td><td>{score(a['acceptedCoverage'])}</td><td>{score(b['acceptedCoverage'])}</td></tr><tr><td>Правильных среди выданных</td><td>{score(a['acceptedAccuracy'])}</td><td>{score(b['acceptedAccuracy'])} ({b['acceptedCount']} ответов)</td></tr></table><p><strong>Общая точность не выросла.</strong> Поэтому обычный режим сохранён по умолчанию. Осторожный режим чаще отказывается отвечать; ноль ошибок среди его 233 выданных ответов на этой выборке не гарантирует правильности на новых видео. Отказ не означает, что ученик показал неправильно. Точность на личной камере не измерялась.</p><p>Одинаковые пороги: вероятность ≥0,70, отрыв от второго класса ≥0,20, кисть найдена минимум в 8 из 16 кадров, результат не no_event. Это вероятности модели, не оценка преподавателя.</p><h2>Что обучено и что не обучено</h2><p>Только отдельные буквы. Непрерывная дактильная речь, слова, свободные фразы, грамматика, лицо и корпус не распознаются. Распознавание не исправляет скелет и анимации аватара. В новых диалогах ответы выбираются по заранее написанным сценариям; понимание видео и повторение ошибок проверяются правилами, а не выдаются за обученный ИИ.</p><h2>Результаты по буквам</h2><table><tr><th>Класс</th><th>Обычная</th><th>Осторожная</th></tr>{rows}</table><p><a href="/models/rsl/alphabet-cautious-report.json">Результаты и матрица ошибок</a> · <a href="/models/rsl/alphabet-cautious-provenance.json">Происхождение данных</a> · <a href="https://github.com/ai-forever/bukva">Bukva</a> · <a href="/research/rsl/bukva-license.pdf">Лицензия</a></p><p>Файл обучения: <code>ml/rsl/train_alphabet_v3.py</code>. Модель: <code>alphabet-cautious-classifier.json</code>. Проверка экспорта в JavaScript: все 34 класса; вероятности совпадают с Python с допуском 10⁻⁷.</p></html>'''
(ROOT/'frontend/public/research/rsl/alphabet-comparison.html').write_text(page)
